// Client-side filtering for hub/problems.html and hub/glossary.html (generated by scripts/build_knowledge.py).
// Items: [data-kn-item] with data-search, data-topics (space separated), optional data-kinds.
// Groups: [data-kn-group] are hidden when none of their items is visible.
// ?q=<text>&topic=<slug>&kind=<kind> pre-fill the filters (handy for links from other pages).
(() => {
  const q = document.getElementById("kn-q");
  if (!q) return;
  const topicSel = document.getElementById("kn-topic");
  const kindSel = document.getElementById("kn-kind");
  const items = [...document.querySelectorAll("[data-kn-item]")];
  const groups = [...document.querySelectorAll("[data-kn-group]")];
  const visibleEl = document.getElementById("kn-visible");
  const totalEl = document.getElementById("kn-total");
  if (totalEl) totalEl.textContent = items.length;

  const params = new URLSearchParams(location.search);
  if (params.get("q")) q.value = params.get("q");
  if (params.get("topic") && topicSel) topicSel.value = params.get("topic");
  if (params.get("kind") && kindSel) kindSel.value = params.get("kind");

  function apply() {
    const words = q.value.toLowerCase().split(/\s+/).filter(Boolean);
    const topic = topicSel ? topicSel.value : "";
    const kind = kindSel ? kindSel.value : "";
    let shown = 0;
    for (const it of items) {
      const hay = it.dataset.search || "";
      const ok = words.every((w) => hay.includes(w))
        && (!topic || (it.dataset.topics || "").split(" ").includes(topic))
        && (!kind || (it.dataset.kinds || "").split(" ").includes(kind));
      it.hidden = !ok;
      if (ok) shown++;
    }
    for (const g of groups) g.hidden = !g.querySelector("[data-kn-item]:not([hidden])");
    if (visibleEl) visibleEl.textContent = shown;
  }

  q.addEventListener("input", apply);
  topicSel?.addEventListener("change", apply);
  kindSel?.addEventListener("change", apply);
  apply();
})();
